mapper.update:
update review
rating = #{rating}, content = #{content},
where id = #{id}

mapper.select:
select id, user_id, anime_id, rating, content, created_at, updated_at
from review
where id = #{id}

select r.id, r.user_id, r.anime_id, r.rating, r.content, r.created_at, r.updated_at, a.title, a.cover from review r left join anime a on r.anime_id = a.id
r.anime_id = #{animeId}
order by r.id desc
